export const stationByCode=code=>stations.find(s=>s.code===code);
export const stationLabel=code=>{const s=stationByCode(code);return `${s.name} (${s.code})`;};
export function resolveStation(value){const q=value.trim().toLowerCase();return stations.find(s=>s.code.toLowerCase()===q||s.name.toLowerCase()===q||stationLabel(s.code).toLowerCase()===q);}
export const minutes=(time,day=0)=>time.split(':').reduce((h,m)=>Number(h)*60+Number(m))+day*1440;
export function findTrains(from,to){if(from===to)return [];return trains.flatMap(train=>{const first=train.stops.findIndex(s=>s.code===from);const last=train.stops.findIndex(s=>s.code===to);if(first<0||last<=first)return [];const segment=train.stops.slice(first,last+1);const departure=segment[0];const arrival=segment.at(-1);return [{...train,segment,departure,arrival,duration:minutes(arrival.arrival,arrival.arrivalDay)-minutes(departure.departure,departure.departureDay),dayDifference:arrival.arrivalDay-departure.departureDay}];});}
export function validateSearch(fromText,toText){if(!fromText.trim()||!toText.trim())return {error:'Choose both a departure and a destination station.'};const from=resolveStation(fromText),to=resolveStation(toText);if(!from||!to)return {error:'Choose a station from the suggestions, or enter its full name or station code.'};if(from.code===to.code)return {error:'Choose two different stations for your journey.'};return {from,to};}
export function formatDuration(value){return `${Math.floor(value/60)}h ${String(value%60).padStart(2,'0')}m`;}
